#include "OdaikoCoreState.inc"
static inline double rand01(void){uint32_t s=rngState;s^=s<<13;s^=s>>17;s^=s<<5;rngState=s;return ((double)s)/4294967296.0;}
static void start_event(int slot){Event *ev=&events[slot];if(ev->kind){double impulse=cfg.bachiMass*ev->velocity*ev->rimScale;for(int i=0;i<nShell;i++){double sign=(i%4<2)?1.0:-1.0,weight=1.0/(1.0+0.10*i);sv[i]+=sign*impulse*0.24*weight;}rimTransientEnv+=clampd(ev->velocity/5.0,0.15,2.5)*ev->transientScale;return;}if(activeCount>=MAX_CONTACTS)return;double *sh=&eventShapes[slot*MAX_HEAD];for(int i=0;i<nFront;i++)fshape[i]=sh[i];double skin=0,skinv=0;for(int i=0;i<nFront;i++){skin+=fq[i]*fshape[i];skinv+=fv[i]*fshape[i];}Contact *ct=&contacts[activeCount++];ct->z=skin+1e-7;ct->v=skinv+ev->relativeVelocity;ct->lastForce=0;ct->age=0;ct->maxForce=0;ct->impulse=0;ct->transientScale=ev->transientScale;ct->contactScale=ev->contactScale;ct->relativeVelocity=ev->relativeVelocity;ct->tangential=ev->tangential;ct->ever=0;ct->contactSamples=0;}
static inline double nonlinear_boost(double env,double scale){double n=clampd(env/3.5,0,6),raw=(cfg.energyResponse==1.0)?n:js_pow(n,cfg.energyResponse),safe=raw/(1.0+raw*cfg.nlSafety);return 1.0+cfg.nlStrength*scale*safe;}
static double room_process(float inputf){double input=(double)inputf;if(!roomEnabled||cfg.roomWet<=1e-5)return input;double pre=input;if(roomPreDelay>0){pre=roomPre[roomPreIdx];roomPre[roomPreIdx]=inputf;roomPreIdx++;if(roomPreIdx>roomPreDelay)roomPreIdx=0;}double rvv=0;for(int k=0;k<6;k++){int j=roomIdx[k];float out=roomBuf[k][j];roomLp[k]+=((double)out-roomLp[k])*(1.0-cfg.roomDamp*0.72);roomBuf[k][j]=(float)(pre+roomLp[k]*roomGain[k]);j++;if(j>=roomDelay[k])j=0;roomIdx[k]=j;rvv+=(double)out;}roomEarly[roomEarlyIdx]=inputf;double early=0;for(int k=0;k<4;k++){int j=roomEarlyIdx-roomEarlyDelay[k];if(j<0)j+=roomEarlyLen;early+=(double)roomEarly[j]*(cfg.roomEarlyLevel/(k+1.0));}roomEarlyIdx++;if(roomEarlyIdx>=roomEarlyLen)roomEarlyIdx=0;rvv=rvv/2.4494897427831780982+early;return input+cfg.roomWet*rvv;}

int process_quantum(int frames){if(frames<0||frames>MAX_BLOCK)return -1;
 for(int bi=0;bi<frames;bi++){
  int n=currentFrame+bi;while(eventCount>0&&events[eventHead].targetFrame<=n){int slot=eventHead;start_event(slot);eventHead=(eventHead+1)%MAX_EVENTS;eventCount--;}
  double meanF=0,meanR=0,meanVF=0,meanVR=0,localW=0,localV=0,eFront=0,eRear=0,meanAllV=0,boundaryV=0;
  for(int i=0;i<nFront;i++){double q=fq[i],v=fv[i],mw=fmean[i];if(fm[i]==0){meanF+=q*mw;meanVF+=v*mw;}localW+=q*fshape[i];localV+=v*fshape[i];eFront+=fev[i]*v*v+feq[i]*q*q;meanAllV+=v;if(i<24)boundaryV+=v*fboundary[i]/24.0;}meanAllV/=nFront;
  for(int i=0;i<nRear;i++){double q=rq[i],v=rv[i],mw=rmean[i];if(rm[i]==0){meanR+=q*mw;meanVR+=v*mw;}eRear+=revscale[i]*v*v+reqscale[i]*q*q;if(i<24)boundaryV+=v*rboundary[i]/24.0;}
  double pCav=cfg.cavityBulk*cfg.area*(meanF+meanR)/cfg.volume;cavityPressureLP+=(pCav-cavityPressureLP)*cfg.cavityPressureAlpha;double cavOut=0,fbF=0,fbR=0;
  for(int i=0;i<nCav;i++){double volumeVelocity=cfg.area*(meanVF*cfrontsign[i]+meanVR*crearsign[i]);double drive=(volumeVelocity/cfg.volume)*comega[i]*42.0*coverlap[i]*cfg.couplingScale;double q0=cq[i],v0=cv[i],qeq=drive*cinvw2[i];double nq=ca11[i]*q0+ca12[i]*v0+(1.0-ca11[i])*qeq;double nv=ca21[i]*q0+ca22[i]*v0-ca21[i]*qeq;cq[i]=nq;cv[i]=nv;double pMode=nq*cfg.cavityPressureFactor*coverlap[i]*cfg.couplingScale*1e-3;fbF+=pMode*cfrontsign[i];fbR+=pMode*crearsign[i];cavOut+=nv*cgain[i]*cfg.cavityNorm;}
  pCav=cavityPressureLP;double pFront=pCav+fbF,pRear=pCav+fbR;
  double contactForce=0,textureForce=0,textureDeriv=0,contactTangential=0;
  for(int c=activeCount-1;c>=0;c--){Contact *ct=&contacts[c];double delta=ct->z-localW,relV=ct->v-localV,F=0;if(delta>0){double base=cfg.contactK*ct->contactScale*js_pow(delta,cfg.contactExponent);double loss=clampd(1.0+cfg.contactLoss*0.18*clampd(relV,-10,20),0.12,3.0);F=dmax(0,base*loss);ct->ever=1;}contactForce+=F;textureForce+=F*ct->transientScale;contactTangential=dmax(contactTangential,ct->tangential);if(F>0){ct->maxForce=dmax(ct->maxForce,F);ct->impulse+=F*cfg.dt;ct->contactSamples++;}double dF=(F-ct->lastForce)*cfg.sampleRate;textureDeriv+=dF*ct->transientScale;ct->lastForce=F;ct->v+=(-F/cfg.contactMassDen)*cfg.dt;ct->z+=ct->v*cfg.dt;ct->age+=cfg.dt;if((ct->ever&&delta<=0&&relV<0)||ct->age>0.020){for(int j=c;j<activeCount-1;j++)contacts[j]=contacts[j+1];activeCount--;}}
  nlEnvFront+=(eFront-nlEnvFront)*cfg.nlAlpha;nlEnvRear+=(eRear-nlEnvRear)*cfg.nlAlpha;double pitch=nonlinear_boost(nlEnvFront,1.0),rpitchb=nonlinear_boost(nlEnvRear,0.86);int fj=0,rj=0;double ff=0,rf=0;if(pitch>1){double u=clampd((pitch-1.0)/0.35,0,1)*95.0;fj=(int)u;if(fj>94)fj=94;ff=u-fj;}if(rpitchb>1){double u=clampd((rpitchb-1.0)/0.35,0,1)*95.0;rj=(int)u;if(rj>94)rj=94;rf=u-rj;}
  double shellBoundary=0;for(int i=0;i<nShell;i++)shellBoundary+=sv[i]*sgain[i]*cfg.shellNorm;double recipMem=-cfg.reciprocalGain*shellBoundary,recipShell=cfg.reciprocalGain*boundaryV;
  double frontOut=0,rearOut=0,sideOut=0,frontState=0,rearState=0;
  for(int i=0;i<nFront;i++){double q0=fq[i],v0=fv[i],drive=(contactForce>0?contactForce*fshape[i]*finv[i]:0)+pFront*ffastcav[i]+recipMem*ffastboundary[i]+(meanAllV-v0)*ffastcross[i];double a11=fa11[i],a12=fa12[i],a21=fa21[i],a22=fa22[i],iw=finvw2[i];if(i<frontNonlinear&&pitch>1){int o=i*PITCH_STRIDE+fj*5;a11=fpitch[o]+(fpitch[o+5]-fpitch[o])*ff;a12=fpitch[o+1]+(fpitch[o+6]-fpitch[o+1])*ff;a21=fpitch[o+2]+(fpitch[o+7]-fpitch[o+2])*ff;a22=fpitch[o+3]+(fpitch[o+8]-fpitch[o+3])*ff;iw=fpitch[o+4]+(fpitch[o+9]-fpitch[o+4])*ff;}double qeq=drive*iw,nq=a11*q0+a12*v0+(1-a11)*qeq,nv=a21*q0+a22*v0-a21*qeq;fq[i]=nq;fv[i]=nv;frontState+=nv*cfg.frontNorm;frontOut+=nv*fmic[i]*cfg.frontNorm;if(fm[i]>0)sideOut+=nv*fside[i]*fsidefactor[i]*cfg.frontNorm;}
  for(int i=0;i<nRear;i++){double q0=rq[i],v0=rv[i],drive=pRear*rfastcav[i]+recipMem*rfastboundary[i];double a11=ra11[i],a12=ra12[i],a21=ra21[i],a22=ra22[i],iw=rinvw2[i];if(i<rearNonlinear&&rpitchb>1){int o=i*PITCH_STRIDE+rj*5;a11=rpitch[o]+(rpitch[o+5]-rpitch[o])*rf;a12=rpitch[o+1]+(rpitch[o+6]-rpitch[o+1])*rf;a21=rpitch[o+2]+(rpitch[o+7]-rpitch[o+2])*rf;a22=rpitch[o+3]+(rpitch[o+8]-rpitch[o+3])*rf;iw=rpitch[o+4]+(rpitch[o+9]-rpitch[o+4])*rf;}double qeq=drive*iw,nq=a11*q0+a12*v0+(1-a11)*qeq,nv=a21*q0+a22*v0-a21*qeq;rq[i]=nq;rv[i]=nv;rearState+=nv*cfg.rearNorm;rearOut+=nv*rmic[i]*cfg.rearNorm;if(rm[i]>0)sideOut+=0.55*nv*rside[i]*rsidefactor[i]*cfg.rearNorm;}
  double shellDrive=recipShell*0.012+pCav*1e-5+rimTransientEnv*0.030,shellOut=0;for(int i=0;i<nShell;i++){double q0=sq[i],v0=sv[i],drive=shellDrive*cfg.shellModeGain*sgain[i],qeq=drive*sinvw2[i],nq=sa11[i]*q0+sa12[i]*v0+(1-sa11[i])*qeq,nv=sa21[i]*q0+sa22[i]*v0-sa21[i]*qeq;sq[i]=nq;sv[i]=nv;shellOut+=nv*sgain[i]*cfg.shellNorm;}
  double standDrive=shellOut*cfg.reciprocalGain*0.35,standEq=standDrive*cfg.standInvOmega2,nstandQ=cfg.standA11*standQ+cfg.standA12*standV+(1-cfg.standA11)*standEq,nstandV=cfg.standA21*standQ+cfg.standA22*standV-cfg.standA21*standEq;standQ=nstandQ;standV=nstandV;double floorDrive=(shellOut+0.75*standV)*cfg.floorCoupling*0.22,floorEq=floorDrive*cfg.floorInvOmega2,nfloorQ=cfg.floorA11*floorQ+cfg.floorA12*floorV+(1-cfg.floorA11)*floorEq,nfloorV=cfg.floorA21*floorQ+cfg.floorA22*floorV-cfg.floorA21*floorEq;floorQ=nfloorQ;floorV=nfloorV;double bodyOut=shellOut*cfg.shellRadiationGain+standV*0.11+floorV*0.16;
  double white=2.0*rand01()-1.0;noiseLP+=0.13*(white-noiseLP);double hp=white-noiseLP,forceNorm=clampd(textureForce/2200.0,0,3),derivNorm=clampd(absd(textureDeriv)/2.5e6,0,3),tang=dmax(contactTangential,cfg.baseTangential);double transient=(0.050+0.750*cfg.hardness*cfg.hardness)*(1+0.55*tang)*hp*(0.60*forceNorm+0.40*derivNorm)+0.18*rimTransientEnv*hp;rimTransientEnv*=cfg.rimDecay;
  double sample=(cfg.radiationFront*frontOut+cfg.radiationRear*rearOut+cfg.radiationSide*sideOut+cfg.radiationBody*bodyOut+cfg.cavityModeGain*0.045*cavOut)*cfg.distanceGain;sample+=transient*(1+1.6*cfg.contactGain);sample*=cfg.masterGain;float dry=(float)sample;outFront[bi]=(float)(frontOut*cfg.masterGain);outRear[bi]=(float)(rearOut*cfg.masterGain);outBody[bi]=(float)(bodyOut*cfg.masterGain);outFrontState[bi]=(float)frontState;outRearState[bi]=(float)rearState;outShellState[bi]=(float)shellBoundary;outDry[bi]=dry;peakDry=dmax(peakDry,absd(sample));outWet[bi]=(float)room_process(dry);
 }
 currentFrame+=frames;return frames;
}
int get_current_frame(void){return currentFrame;}
double get_peak(void){return peakDry;}